def fib(n):
    # Base case: if n is 0 or 1, return n
    if n <= 1:
        return n

    # Recursive case: F(n) = F(n-1) + F(n-2)
    return fib(n - 1) + fib(n - 2)

def countOdds(low: int, high: int) -> int:
    # Check if both low and high are even
    if low % 2 == 0 and high % 2 == 0:
        return (high - low) // 2
    # Check if both low and high are odd
    elif low % 2 == 1 and high % 2 == 1:
        return ((high - low) + 2) // 2
    # One is even, one is odd
    else:
        return ((high - low) + 1) // 2

def numPrimeArrangements(n: int) -> int:
    MOD = 10**9 + 7

    # Function to check if a number is prime
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Count prime indices (1-indexed)
    prime_indices = 0
    for i in range(1, n + 1):
        if is_prime(i):
            prime_indices += 1

    # Count prime numbers (1 to n)
    prime_numbers = 0
    for i in range(1, n + 1):
        if is_prime(i):
            prime_numbers += 1

    # If number of prime indices != number of prime numbers, it's impossible
    if prime_indices != prime_numbers:
        return 0

    # Calculate factorial of prime_indices and (n - prime_indices)
    def factorial(x):
        result = 1
        for i in range(1, x + 1):
            result = (result * i) % MOD
        return result

    result = (factorial(prime_indices) * factorial(n - prime_indices)) % MOD
    return result

