def isPowerOfFour(n):
    # If n is less than or equal to 0, it cannot be a power of four
    if n <= 0:
        return False

    # Keep dividing by 4 while n is divisible by 4
    while n % 4 == 0:
        n = n // 4

    # If n becomes 1, it was a power of four
    return n == 1

def isPowerOfTwo(n):
    # If n is 0, it's not a power of two
    if n == 0:
        return False

    # If n is 1, it is a power of two (2^0 = 1)
    if n == 1:
        return True

    # For n > 1, repeatedly divide by 2 while n is even
    while n % 2 == 0:
        n = n // 2

    # If we reached 1, then n was a power of two
    return n == 1

