def countNumbersWithUniqueDigits(n):
    if n == 0:
        return 1
    if n == 1:
        return 10

    # For n > 1, we need to calculate the count
    # The pattern is: 9 * 9 * 8 * 7 * ... for the first few digits
    # But we also need to add the count for smaller digit numbers

    # Calculate the count of n-digit numbers with unique digits
    # First digit: 9 choices (1-9), second digit: 9 choices (0-9 except first), etc.
    unique_count = 9
