def calculate(s: str) -> int:
    # Initialize variables
    num = 0
    ope = '+'  # Start with '+' to handle first number
    stack = []

    # Process each character
    for i in range(len(s)):
        char = s[i]

        # If character is a digit, build the number
        if char.isdigit():
            num = num * 10 + int(char)

        # If character is an operator or we're at the end of string
        if char in '+-*/' or i == len(s) - 1:
            # Process the current number with the current operator
            if ope == '+':
                stack.append(num)
            elif ope == '-':
                stack.append(-num)
            elif ope == '*':
                stack.append(stack.pop() * num)
            elif ope == '/':
                # Integer division truncates toward zero
                # For negative numbers, we need to handle carefully
                top = stack.pop()
                if top < 0:
                    stack.append(-(-top // num))
                else:
                    stack.append(top // num)

            # Update operator and reset number
            ope = char
            num = 0

    # Sum all elements in stack
