def largestDivisibleSubset(nums):
    # Sort the numbers to process in ascending order
    nums.sort()

    # Initialize dp array where dp[i] stores the longest subset ending at nums[i]
    n = len(nums)
    dp = [[] for _ in range(n)]

    # Initialize each element as a subset of itself
    for i in range(n):
        dp[i] = [nums[i]]

    # Fill the dp array
    for i in range(n):
        for j in range(i):
            # Check if nums[i] is divisible by nums[j]
            if nums[i] % nums[j] == 0:
                # If we can extend the subset ending at j with nums[i]
                if len(dp[j]) + 1 > len(dp[i]):
                    dp[i] = dp[j] + [nums[i]]

    # Find the longest subset
    result = max(dp, key=len)

    return result

