def myPow(x: float, n: int) -> float:
    # Handle the case where n is negative
    if n < 0:
        return 1 / myPow(x, -n)

    # Base cases
    if x == 0:
        return 0
    if n == 0:
        return 1

    # Recursive case - divide and conquer
    # Calculate x^(n//2)
    res = myPow(x, n // 2)

    # Square the result
    res = res * res

    # If n is odd, multiply by one more x
    if n % 2 == 1:
        res = res * x

    return res

