def numberOfBoomerangs(points: List[List[int]]) -> int:
    def distance(p1, p2):
        return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

    ans = 0

    # For each point as the center of the boomerang
    for i in range(len(points)):
        # Dictionary to store count of points at each distance from points[i]
        distance_count = {}

        # Calculate distances from points[i] to all other points
        for j in range(len(points)):
            if i != j:  # Skip the same point
                d = distance(points[i], points[j])
                distance_count[d] = distance_count.get(d, 0) + 1

        # For each distance, if k points are at that distance,
        # we can form k*(k-1) boomerangs (choose 2 points from k)
        for count in distance_count.values():
            if count >= 2:
                ans += count * (count - 1)

    return ans

