def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)

    # Edge case: single element
    if n == 1:
        return True

    # Edge case: contains 1
    if 1 in nums:
        return False

    # Find all prime factors of a number
    def get_prime_factors(num):
        factors = set()
        d = 2
        while d * d <= num:
            while num % d == 0:
                factors.add(d)
                num //= d
            d += 1
        if num > 1:
            factors.add(num)
        return factors

    # Union-Find data structure
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Map prime factor to index
    prime_to_index = {}

    # For each number, find its prime factors and union all numbers sharing the same factor
    for i, num in enumerate(nums):
        factors = get_prime_factors(num)
        for factor in factors:
            if factor in prime_to_index:
                # Union current number with the first number that had this factor
                union(i, prime_to_index[factor])
            else:
                # Record the first number with this factor
                prime_to_index[factor] = i

    # Check if all numbers are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True

def preimageSizeFZF(k: int) -> int:
