def isRationalEqual(S, T):
    def f(s):
        # Validate input format
        if s.count('.') > 1:
            raise ValueError("Invalid format: multiple decimal points")
        if s.count('(') != s.count(')'):
            raise ValueError("Invalid format: mismatched parentheses")

        # Find the index of '(' if it exists
        i = s.find('(')

        # If no '(' found, it's a simple number
        if i == -1:
            # Convert to float directly
            return float(s)

        # Find the decimal point
        decimal_idx = s.find('.')

        # Extract integer part
        if decimal_idx == -1:
            integer_part = s[:i]
        else:
            integer_part = s[:decimal_idx]

        # Extract non-repeating part
        if decimal_idx == -1:
            non_repeating = ""
        else:
            non_repeating = s[decimal_idx + 1:i]

        # Extract repeating part
        repeating = s[i + 1:-1]  # Remove '(' and ')'

        # Convert integer part to float
        result = float(integer_part) if integer_part else 0.0

        # Add non-repeating part
        if non_repeating:
            result += float('0.' + non_repeating)

        # Add repeating part
        if repeating:
            # Calculate the value of the repeating part
            repeating_value = int(repeating) / (10 ** len(repeating) - 1)
            # Adjust for the position (after non-repeating part)
            if non_repeating:
                repeating_value /= (10 ** len(non_repeating))
            result += repeating_value

        return result

    return abs(f(S) - f(T)) < 1e-10

def maximumSum(nums: List[int]) -> int:
    import math

    def get_square_free_part(num):
        result = 1
        for i in range(2, int(math.sqrt(num)) + 1):
            count = 0
            while num % i == 0:
                num //= i
                count += 1
            if count % 2 == 1:
                result *= i
        if num > 1:
            result *= num
        return result

    n = len(nums)
    max_sum = 0

    # Group indices by their square-free part
    groups = {}
    for i in range(1, n + 1):
        square_free = get_square_free_part(i)
        if square_free not in groups:
            groups[square_free] = []
        groups[square_free].append(i)

    # For each group, calculate the sum of elements at those indices
    for group in groups.values():
        total = 0
        for index in group:
            if index <= n:
                total += nums[index - 1]  # Convert to 0-indexed
        max_sum = max(max_sum, total)

    return max_sum

def reachingPoints(sx, sy, tx, ty):
    # Work backwards from (tx, ty) to (sx, sy)
    while tx >= sx and ty >= sy:
        # If we've reached the target
        if tx == sx and ty == sy:
            return True

        # If tx > ty, the previous state must have been (tx - ty, ty)
        # But we can optimize using modulo
        if tx > ty:
            # Instead of subtracting ty repeatedly, use modulo
            if ty == sy:
                # If ty is already at target, we can only reduce tx
                # Check if we can reach sx from tx
                return (tx - sx) % ty == 0
            tx = tx % ty
        else:
            # ty > tx, previous state was (tx, ty - tx)
            if tx == sx:
                # If tx is already at target, we can only reduce ty
                # Check if we can reach sy from ty
                return (ty - sy) % tx == 0
            ty = ty % tx

        # If either becomes less than target, we can't reach
        if tx < sx or ty < sy:
            return False

    return False

def makeStringSorted(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)

    # Count frequency of each character
    cnt = [0] * 26
    for char in s:
        cnt[ord(char) - ord('a')] += 1

    # Precompute factorials and modular inverses
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # Function to compute modular inverse using Fermat's little theorem
    def mod_inverse(a, mod):
        return pow(a, mod - 2, mod)

    # Calculate total permutations with duplicates
    total_permutations = fact[n]
    for count in cnt:
        if count > 0:
            total_permutations = (total_permutations * mod_inverse(fact[count], MOD)) % MOD

    # Calculate the rank of the string
    ans = 0
    for i in range(n):
        # Count characters smaller than s[i] that can be placed at position i
        smaller_count = 0
        for j in range(ord(s[i]) - ord('a')):
            if cnt[j] > 0:
                smaller_count += cnt[j]

        # Calculate permutations with smaller characters at position i
        if smaller_count > 0:
            # Remaining positions after position i
            remaining = n - i - 1
            # Calculate permutations of remaining characters
            remaining_permutations = fact[remaining]
            for j in range(26):
                if cnt[j] > 0:
                    # Adjust for the current character's count
                    if j == ord(s[i]) - ord('a'):
                        # Use the current count (before removal) for the denominator
                        remaining_permutations = (remaining_permutations * mod_inverse(fact[cnt[j]], MOD)) % MOD
                    else:
                        remaining_permutations = (remaining_permutations * mod_inverse(fact[cnt[j]], MOD)) % MOD

            # Add permutations with smaller characters at position i
            ans = (ans + smaller_count * remaining_permutations) % MOD

        # Remove current character from available characters
        cnt[ord(s[i]) - ord('a')] -= 1

    return ans

