def maxValueAfterReverse(nums: List[int]) -> int:
    n = len(nums)

    # Calculate initial total value
    total = 0
    for i in range(n - 1):
        total += abs(nums[i] - nums[i + 1])

    # If array has only 2 elements, reversing gives the same result
    if n == 2:
        return total

    max_total = total

    # Try all possible subarrays to reverse
    for l in range(n):
        for r in range(l, n):
            # Calculate the change in total value
            new_total = total

            # Remove the original boundary connections
            if l > 0:
                new_total -= abs(nums[l - 1] - nums[l])
            if r < n - 1:
                new_total -= abs(nums[r] - nums[r + 1])

            # Add the new boundary connections
            if l > 0:
                new_total += abs(nums[l - 1] - nums[r])
            if r < n - 1:
                new_total += abs(nums[l] - nums[r + 1])

            # Remove the internal differences that change due to reversal
            for i in range(l, r):
                new_total -= abs(nums[i] - nums[i + 1])

            # Add the new internal differences after reversal
            for i in range(l, r):
                # The new adjacent pair after reversal is (nums[r - (i - l)], nums[r - (i - l) - 1])
                # But we need to ensure the indices are valid
                new_idx1 = r - (i - l)
                new_idx2 = new_idx1 - 1
                if new_idx1 < n and new_idx2 >= 0:
                    new_total += abs(nums[new_idx1] - nums[new_idx2])

            max_total = max(max_total, new_total)

    return max_total

def kMirror(k: int, n: int) -> int:
    def to_base_k(num, base):
