        # Check if it's palindrome in base-k
        base_k_repr = to_base_k(num, k)
        return is_palindrome(base_k_repr)

    # Input validation
    if not isinstance(k, int) or not isinstance(n, int):
        raise ValueError("k and n must be integers")
    if k < 2 or k > 9:
        raise ValueError("k must be between 2 and 9")
    if n < 1:
        raise ValueError("n must be at least 1")

    count = 0
    total_sum = 0
    num = 1

    while count < n:
        if is_k_mirror(num, k):
            total_sum += num
            count += 1
        num += 1

    return total_sum

def get_max_i_j(points):
    if len(points) <= 1:
        return 0, 0, 0

    # Calculate p = x + y and m = x - y for each point
    p = [x + y for x, y in points]
    m = [x - y for x, y in points]

    # Find the indices of min and max values
    pmin_idx = 0
    pmax_idx = 0
    for i in range(1, len(points)):
        if p[i] < p[pmin_idx]:
            pmin_idx = i
        if p[i] > p[pmax_idx]:
            pmax_idx = i

    mmin_idx = 0
    mmax_idx = 0
    for i in range(1, len(points)):
        if m[i] < m[mmin_idx]:
            mmin_idx = i
        if m[i] > m[mmax_idx]:
            mmax_idx = i

    # Check which difference is larger
    p_diff = p[pmax_idx] - p[pmin_idx]
    m_diff = m[mmax_idx] - m[mmin_idx]

    if p_diff >= m_diff:
        return p_diff, pmax_idx, pmin_idx
    else:
        return m_diff, mmax_idx, mmin_idx

def minimumDistance(points):
    n = len(points)
    if n <= 2:
        return 0

    min_max_distance = float('inf')

    # Try removing each point and find the maximum distance
    for i in range(n):
        # Create a new list without the i-th point
        remaining_points = points[:i] + points[i+1:]

        # Find the maximum Manhattan distance among remaining points
        max_distance, _, _ = get_max_i_j(remaining_points)

        # Update the minimum of all maximum distances
        min_max_distance = min(min_max_distance, max_distance)

    return min_max_distance
